const items = $input.all();

if (items.length !== 1) {
  throw new Error('Expected exactly one piece per call.');
}

const input = items[0].json;

function cleanId(value, label) {
  if (typeof value !== 'string') {
    throw new Error(label + ' must be a Drive ID string.');
  }

  const id = value.trim();

  if (!/^[A-Za-z0-9_-]+$/.test(id)) {
    throw new Error(label + ' must be a non-empty ID, not a URL.');
  }

  return id;
}

const pieceFolderId = cleanId(input.pieceFolderId, 'pieceFolderId');

if (!Array.isArray(input.sourceFileIds) || input.sourceFileIds.length === 0) {
  throw new Error('sourceFileIds must be a non-empty array of file IDs.');
}

const sourceFileIds = [...new Set(
  input.sourceFileIds.map((id, index) =>
    cleanId(id, 'sourceFileIds[' + index + ']')
  )
)];

if (sourceFileIds.includes(pieceFolderId)) {
  throw new Error('A source file ID cannot be the piece folder ID.');
}

if(sourceFileIds.length!==1)throw new Error('Exactly one source ZIP is required per piece.');
return [{
  json: {
    pieceFolderId,
    sourceFileIds,
    sourceFileCount: sourceFileIds.length,
    framesPerSecond: 2
  },
  pairedItem: { item: 0 }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error('Expected exactly one piece per call.');
}

const account = items[0].json.data;

if (
  !account ||
  account.email !== 'aura.atelier.by.nada@gmail.com' ||
  account.paying !== false ||
  !Number.isFinite(account.credits) ||
  account.credits < 1
) {
  throw new Error('Expected the AURA free account with available credits.');
}

const piece = $('Validate Piece Input').itemMatching(0).json;

if (
  !piece.pieceFolderId ||
  !Array.isArray(piece.sourceFileIds) ||
  piece.sourceFileIds.length === 0
) {
  throw new Error('Validated piece input is missing.');
}

return [{
  json: {
    ...piece,
    cloudConvertCredits: account.credits
  },
  pairedItem: { item: 0 }
}];

const items = $input.all();

if (items.length === 0) {
  throw new Error('No source file metadata received.');
}

return items.map((item, index) => {
  const file = item.json;
  const piece = $('Prepare Source Files').itemMatching(index).json;

  if (file.id !== piece.sourceFileId) {
    throw new Error('Source file ID does not match the requested file.');
  }

  if (!Array.isArray(file.parents) ||
      !file.parents.includes(piece.pieceFolderId)) {
    throw new Error('Source ZIP does not belong to this piece folder.');
  }

  if (file.trashed !== false ||
      file.capabilities?.canDownload !== true) {
    throw new Error('Source file is trashed or cannot be downloaded.');
  }

  const zipTypes = [
    'application/zip',
    'application/x-zip-compressed',
    'application/x-zip'
  ];

  if (typeof file.name !== 'string' ||
      !file.name.toLowerCase().endsWith('.zip') ||
      !zipTypes.includes(file.mimeType)) {
    throw new Error('Expected a ZIP archive for this extraction workflow.');
  }

  if(/^AURA_reference_images_.*\.zip$/i.test(file.name))throw new Error('A generated reference ZIP cannot be used as a source ZIP.');
  const size = Number(file.size);
  if(size>200*1024*1024)throw new Error('Source ZIP exceeds the 200 MiB transfer limit.');

  if (typeof file.size !== 'string' ||
      !/^\d+$/.test(file.size) ||
      !Number.isSafeInteger(size) || size <= 0) {
    throw new Error('Source ZIP has an invalid or empty size.');
  }

  if (!/^[a-f0-9]{32}$/i.test(file.md5Checksum ?? '') ||
      !/^\d+$/.test(file.version ?? '')) {
    throw new Error('Source ZIP checksum or version is missing.');
  }

  return {
    json: {
      ...piece,
      sourceFileName: file.name,
      sourceFileSizeBytes: size,
      sourceFileMetadata: file
    },
    pairedItem: { item: index }
  };
});

const items = $input.all();

if (items.length === 0) {
  throw new Error('No unpacked ZIP data received.');
}

const piece = items[0].json;

if (items.length !== piece.sourceFileCount) {
  throw new Error('Expected all source ZIPs for this piece.');
}

const videoExtensions = new Set([
  'mp4', 'mov', 'm4v', 'avi', 'mkv', 'webm',
  'mpg', 'mpeg', 'mts', 'm2ts', 'wmv', 'flv',
  '3gp', '3g2', 'mxf'
]);

const imageExtensions = new Set([
  'jpg', 'jpeg', 'png', 'webp', 'heic', 'heif',
  'avif', 'tif', 'tiff', 'bmp', 'gif'
]);

const videos = [];
const images = [];
const ignoredFiles = [];
const sourceArchives = [];
const binary = {};
const seenSources = new Set();

for (const item of items) {
  const source = item.json;

  if (source.pieceFolderId !== piece.pieceFolderId ||
      source.framesPerSecond !== piece.framesPerSecond) {
    throw new Error('Cannot combine inputs from different pieces.');
  }

  if (!source.sourceFileId || seenSources.has(source.sourceFileId)) {
    throw new Error('Missing or duplicate source ZIP ID.');
  }

  seenSources.add(source.sourceFileId);
  sourceArchives.push({
    sourceFileId: source.sourceFileId,
    sourceFileName: source.sourceFileName,
    sourceFileSizeBytes: source.sourceFileSizeBytes,
    sourceFileMetadata: source.sourceFileMetadata
  });

  for (const [inputField, file] of Object.entries(item.binary ?? {})) {
    const name = String(file.fileName ?? '').replace(/\\/g, '/');
    const baseName = name.split('/').pop() ?? '';

    if (!name || name.startsWith('/') ||
        /^[A-Za-z]:/.test(name) || name.includes('\u0000') ||
        name.split('/').includes('..')) {
      throw new Error('Unsafe or missing filename in source ZIP.');
    }

    if (name.endsWith('/') || name.split('/').includes('__MACOSX') ||
        baseName === '.DS_Store' || baseName.startsWith('._')) {
      ignoredFiles.push({
        sourceFileId: source.sourceFileId,
        fileName: name,
        reason: 'folder or system metadata'
      });
      continue;
    }

    const extension = String(
      file.fileExtension || baseName.split('.').pop() || ''
    ).replace(/^\./, '').toLowerCase();

    const mimeType = String(file.mimeType ?? '').toLowerCase();
    let kind;

    if (videoExtensions.has(extension) || mimeType.startsWith('video/')) {
      kind = 'video';
    } else if (imageExtensions.has(extension) || mimeType.startsWith('image/')) {
      kind = 'image';
    } else {
      ignoredFiles.push({
        sourceFileId: source.sourceFileId,
        fileName: name,
        reason: 'unsupported file type'
      });
      continue;
    }

    const list = kind === 'video' ? videos : images;
    const assetId = kind + '_' + String(list.length + 1).padStart(4, '0');

    binary[assetId] = file;
    list.push({
      assetId,
      binaryField: assetId,
      sourceFileId: source.sourceFileId,
      sourceBinaryField: inputField,
      originalFileName: name,
      extension,
      mimeType,
      fileSize: file.fileSize ?? null
    });
  }
}

if (videos.length === 0 && images.length === 0) {
  throw new Error('No video or image files found in the source ZIPs.');
}

return [{
  json: {
    pieceFolderId: piece.pieceFolderId,
    sourceFileIds: sourceArchives.map(source => source.sourceFileId),
    sourceFileCount: sourceArchives.length,
    framesPerSecond: piece.framesPerSecond,
    cloudConvertCredits: piece.cloudConvertCredits,
    videoCount: videos.length,
    imageCount: images.length,
    ignoredFileCount: ignoredFiles.length,
    inventoryNeedsReview: ignoredFiles.some(
      file => file.reason === 'unsupported file type'
    ),
    sourceArchives,
    videos,
    images,
    ignoredFiles
  },
  binary,
  pairedItem: items.map((_, index) => ({ item: index }))
}];

const crypto = require('crypto');
const items = $input.all();

if (items.length !== 1) {
  throw new Error('Expected one inventoried piece.');
}

const item = items[0];
const piece = item.json;

if (piece.inventoryNeedsReview !== false) {
  throw new Error('Review unsupported files before creating a job.');
}

if (!Array.isArray(piece.videos) || !Array.isArray(piece.images) ||
    piece.videoCount !== piece.videos.length ||
    piece.imageCount !== piece.images.length ||
    piece.videoCount + piece.imageCount === 0 ||
    piece.framesPerSecond !== 2) {
  throw new Error('Asset inventory or frame-rate setting is invalid.');
}

const pipelineVersion = 'aura-frames-v1';
const engineVersion = '9.0.1';
const tasks = {};
const uploadPlan = [];
const archiveInputs = [];
const binary = {};
const seenAssets = new Set();

const assets = [
  ...piece.videos.map(asset => ({ ...asset, kind: 'video' })),
  ...piece.images.map(asset => ({ ...asset, kind: 'image' }))
];

for (const asset of assets) {
  const file = item.binary?.[asset.binaryField];
  const idPattern = new RegExp('^' + asset.kind + '_[0-9]{4,}$');

  if (!idPattern.test(asset.assetId) ||
      asset.binaryField !== asset.assetId ||
      seenAssets.has(asset.assetId) || !file ||
      !piece.sourceFileIds.includes(asset.sourceFileId) ||
      !/^[a-z0-9]{1,10}$/.test(asset.extension)) {
    throw new Error('Invalid, missing or duplicate asset: ' + asset.assetId);
  }

  seenAssets.add(asset.assetId);

  const stem = asset.originalFileName.split('/').pop()
    .replace(/\.[^.]+$/, '')
    .replace(/[^A-Za-z0-9_-]/g, '_')
    .slice(0, 80) || 'original';

  const uploadFileName = asset.kind === 'video'
    ? asset.assetId + '.' + asset.extension
    : asset.assetId + '__' + stem + '.' + asset.extension;

  const importTask = 'upload-' + asset.assetId;

  tasks[importTask] = { operation: 'import/upload' };

  binary[asset.binaryField] = {
    ...file,
    fileName: uploadFileName,
    fileExtension: asset.extension
  };

  uploadPlan.push({
    ...asset,
    importTask,
    uploadFileName
  });

  if (asset.kind === 'video') {
    const metadataTask = 'inspect-' + asset.assetId;
    const extractTask = 'extract-' + asset.assetId;

    tasks[metadataTask] = {
      operation: 'metadata',
      input: importTask,
      engine: 'ffmpeg',
      engine_version: engineVersion
    };

    const inputPath = '/input/' + importTask + '/' + uploadFileName;
    const outputPath = '/output/' + asset.assetId + '_frame_%06d.jpg';

    tasks[extractTask] = {
      operation: 'command',
      input: importTask,
      engine: 'ffmpeg',
      engine_version: engineVersion,
      command: 'ffmpeg',
      capture_output: true,
      timeout: 300,
      arguments: [
        '-hide_banner -nostdin',
        '-i "' + inputPath + '"',
        '-map 0:v:0 -an',
        '-vf "fps=2"',
        '-c:v mjpeg -qmin 1 -q:v 1',
        '-pix_fmt yuvj444p',
        '"' + outputPath + '"'
      ].join(' ')
    };

    archiveInputs.push(extractTask);
  } else {
    archiveInputs.push(importTask);
  }
}

const jobFingerprint = crypto.createHash('sha256').update(JSON.stringify({
  pipelineVersion,
  sources: piece.sourceArchives,
  tasks,
  uploadNames: uploadPlan.map(asset => asset.uploadFileName)
})).digest('hex');

const outputZipFilename =
  'AURA_reference_images_' + jobFingerprint.slice(0, 12) + '.zip';

tasks['archive-assets'] = {
  operation: 'archive',
  input: archiveInputs,
  output_format: 'zip',
  filename: outputZipFilename,
  timeout: 300
};

tasks['export-assets'] = {
  operation: 'export/url',
  input: 'archive-assets',
  inline: false,
  archive_multiple_files: false
};

return [{
  json: {
    jobSummary: {
      jobsToCreate: 1,
      videoCount: piece.videoCount,
      originalImageCount: piece.imageCount,
      filesToUpload: uploadPlan.length,
      frameExtractionTasks: piece.videoCount,
      totalInternalTasks: Object.keys(tasks).length,
      outputZipFilename
    },
    ...piece,
    pipelineVersion,
    jobFingerprint,
    uploadPlan,
    jobPayload: {
      tag: 'aura-frames:' + piece.pieceFolderId + ':' +
        jobFingerprint.slice(0, 16),
      tasks
    }
  },
  binary,
  pairedItem: { item: 0 }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error('Expected one job lookup response.');
}

const response = items[0].json;
const plan = $('Build CloudConvert Job').itemMatching(0);
const expectedTag = plan.json.jobPayload?.tag;

if (typeof expectedTag !== 'string' || !expectedTag) {
  throw new Error('The planned job tag is missing.');
}

if (!Array.isArray(response.data) || response.links?.next !== null) {
  throw new Error('Unexpected or paginated job lookup. Review before continuing.');
}

if (response.data.length > 1) {
  throw new Error('Multiple matching jobs found. Review before continuing.');
}

const needsNewJob = response.data.length === 0;
const existing = needsNewJob ? null : response.data[0];

if (!needsNewJob) {
  if (!existing || typeof existing.id !== 'string' || !existing.id.trim() ||
      existing.tag !== expectedTag) {
    throw new Error('Existing job does not match the planned piece job.');
  }

  if (!['waiting', 'processing', 'finished'].includes(existing.status)) {
    throw new Error('Existing job failed or has an unexpected status. Review before retrying.');
  }
}

return [{
  json: {
    ...plan.json,
    jobDecision: {
      needsNewJob,
      existingJobId: existing?.id ?? null,
      existingJobStatus: existing?.status ?? null
    }
  },
  binary: plan.binary,
  pairedItem: { item: 0 }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error('Expected one CloudConvert job response.');
}

const plan = $('Resolve CloudConvert Job').itemMatching(0);
const job = items[0].json.data;
const expected = plan.json.jobPayload;
const validStatuses = ['waiting', 'processing', 'finished'];

if (!job || typeof job.id !== 'string' || !job.id.trim() ||
    job.tag !== expected?.tag || !Array.isArray(job.tasks) ||
    !validStatuses.includes(job.status)) {
  throw new Error('Unexpected or failed CloudConvert job. Review before continuing.');
}

if (plan.json.jobDecision?.needsNewJob === false &&
    job.id !== plan.json.jobDecision.existingJobId) {
  throw new Error('The returned job ID does not match the selected existing job.');
}

const plannedTasks = Object.entries(expected.tasks ?? {});
const byName = new Map();
const taskIds = new Set();

for (const task of job.tasks) {
  if (!task || typeof task.name !== 'string' || byName.has(task.name) ||
      typeof task.id !== 'string' || !task.id.trim() || taskIds.has(task.id) ||
      task.job_id !== job.id || !validStatuses.includes(task.status)) {
    throw new Error('Invalid, duplicate or failed job task. Review before continuing.');
  }
  byName.set(task.name, task);
  taskIds.add(task.id);
}

if (!plannedTasks.length || job.tasks.length !== plannedTasks.length) {
  throw new Error('CloudConvert task count does not match the plan.');
}

for (const [name, definition] of plannedTasks) {
  if (byName.get(name)?.operation !== definition.operation) {
    throw new Error('CloudConvert task does not match the plan: ' + name);
  }
}

const uploads = plan.json.uploadPlan;
const importTasks = job.tasks.filter(task => task.operation === 'import/upload');

if (!Array.isArray(uploads) || uploads.length !== importTasks.length ||
    Object.keys(plan.binary ?? {}).length !== uploads.length) {
  throw new Error('The upload plan or attached files are incomplete.');
}

const uploadFields = new Set();
const uploadNames = new Set();

for (const asset of uploads) {
  const file = plan.binary?.[asset.binaryField];
  if (!file || file.fileName !== asset.uploadFileName ||
      uploadFields.has(asset.binaryField) || uploadNames.has(asset.importTask) ||
      byName.get(asset.importTask)?.operation !== 'import/upload') {
    throw new Error('An upload file is missing, duplicated or mismatched.');
  }
  uploadFields.add(asset.binaryField);
  uploadNames.add(asset.importTask);
}

return [{
  json: {
    submissionSummary: {
      jobId: job.id,
      status: job.status,
      taskCount: job.tasks.length,
      filesAttached: uploads.length,
      uploadsWaiting: importTasks.filter(task => task.status === 'waiting').length
    },
    ...plan.json,
    cloudConvertJobId: job.id,
    cloudConvertJobStatus: job.status,
    cloudConvertJob: job
  },
  binary: plan.binary,
  pairedItem: { item: 0 }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error('Expected one attached piece job.');
}

const item = items[0];
const piece = item.json;
const job = piece.cloudConvertJob;

if (!job || job.id !== piece.cloudConvertJobId ||
    job.tag !== piece.jobPayload?.tag ||
    !['waiting', 'processing', 'finished'].includes(job.status) ||
    !Array.isArray(job.tasks) ||
    !Array.isArray(piece.uploadPlan) || !piece.uploadPlan.length) {
  throw new Error('The attached job or upload plan is invalid.');
}

const byName = new Map(job.tasks.map(task => [task.name, task]));
const seenFiles = new Set();
const seenTasks = new Set();
const allowedUploadUrl =
  /^https:\/\/(?:[a-z0-9-]+\.)?(?:storage|upload)\.cloudconvert\.com(?:\/|$)/i;

if (byName.size !== job.tasks.length ||
    Object.keys(item.binary ?? {}).length !== piece.uploadPlan.length) {
  throw new Error('Duplicate tasks or incomplete attached files.');
}

return piece.uploadPlan.map(asset => {
  const task = byName.get(asset.importTask);
  const file = item.binary?.[asset.binaryField];

  if (!task || task.job_id !== job.id || task.operation !== 'import/upload' ||
      !['waiting', 'processing', 'finished'].includes(task.status)) {
    throw new Error('Upload task is not waiting. Refresh and review before retrying.');
  }

  if (!file || file.fileName !== asset.uploadFileName ||
      !/^[A-Za-z0-9_.-]{1,160}$/.test(asset.uploadFileName) ||
      !['video', 'image'].includes(asset.kind) ||
      seenFiles.has(asset.binaryField) || seenTasks.has(task.id)) {
    throw new Error('Missing, unsafe or duplicated upload file.');
  }

  const uploadRequired = task.status === 'waiting';
  const form = uploadRequired ? task.result?.form : {url:'https://storage.cloudconvert.com/',parameters:{skip:'true'}};
  const parameters = form?.parameters;

  if (typeof form?.url !== 'string' || !allowedUploadUrl.test(form.url) ||
      /[\r\n]/.test(form.url) ||
      !parameters || typeof parameters !== 'object' ||
      Array.isArray(parameters) || !Object.keys(parameters).length) {
    throw new Error('Missing or unexpected CloudConvert upload form.');
  }

  for (const [name, value] of Object.entries(parameters)) {
    if (!/^[A-Za-z0-9_.-]+$/.test(name) || name.toLowerCase() === 'file' ||
        !['string', 'number', 'boolean'].includes(typeof value) ||
        (typeof value === 'number' && !Number.isFinite(value))) {
      throw new Error('Unexpected upload form field. Review before continuing.');
    }
  }

  seenFiles.add(asset.binaryField);
  seenTasks.add(task.id);

  return {
    json: {
      uploadRequired,
      uploadSummary: {
        jobId: job.id,
        assetId: asset.assetId,
        kind: asset.kind,
        fileName: asset.uploadFileName,
        taskStatus: task.status
      },
      pieceFolderId: piece.pieceFolderId,
      cloudConvertJobId: job.id,
      assetId: asset.assetId,
      kind: asset.kind,
      sourceFileId: asset.sourceFileId,
      importTask: asset.importTask,
      importTaskId: task.id,
      uploadFileName: asset.uploadFileName,
      uploadUrl: form.url,
      uploadParameters: { ...parameters }
    },
    binary: { file },
    pairedItem: { item: 0 }
  };
});

const crypto = require('crypto');
const items = $input.all();
if (items.length !== 1) throw new Error('Expected one file per upload.');
const item=items[0], data=item.json, fields=data.uploadParameters;
if (data.uploadRequired !== true || !item.binary?.file ||
    !/^https:\/\/(?:[a-z0-9-]+\.)?(?:storage|upload)\.cloudconvert\.com(?:\/|$)/i.test(data.uploadUrl) ||
    !/^[A-Za-z0-9_.-]{1,160}$/.test(data.uploadFileName) || !fields || Array.isArray(fields)) {
  throw new Error('Invalid native-upload context.');
}
const nativeFormFields=Object.entries(fields).map(([name,value])=>{
  if(!/^[A-Za-z0-9_.-]+$/.test(name) || name.toLowerCase()==='file' ||
     !['string','number','boolean'].includes(typeof value) ||
     (typeof value==='number'&&!Number.isFinite(value))) throw new Error('Invalid upload form field.');
  return {parameterType:'formData',name,value:String(value)};
});
if(nativeFormFields.length!==8) throw new Error('CloudConvert changed its upload field count. Review the form before uploading; no fields will be silently omitted.');
if(fields.Policy){
  const policy=JSON.parse(Buffer.from(String(fields.Policy),'base64').toString('utf8'));
  if(!Number.isFinite(Date.parse(policy.expiration)) || Date.parse(policy.expiration)<=Date.now()+60000)
    throw new Error('Upload form is expired or about to expire. Refresh the existing job.');
}
const source=await this.helpers.getBinaryDataBuffer(0,'file');
if(!source.length) throw new Error('Empty upload file.');
nativeFormFields.push({parameterType:'formBinaryData',name:'file',inputDataFieldName:'file'});
return [{json:{...data,nativeFormFields,sourceFileBytes:source.length,
  sourceSha256:crypto.createHash('sha256').update(source).digest('hex'),
  expectedUploadStatusCode:Number(fields.success_action_status||201)},
  binary:{file:item.binary.file},pairedItem:{item:0}}];

const response=$input.first().json;
const item=$('Build CloudConvert Upload Body').itemMatching(0);
const data=item.json;
if(response.statusCode!==data.expectedUploadStatusCode) throw new Error('Upload not confirmed: HTTP '+response.statusCode);
return [{json:{cloudConvertJobId:data.cloudConvertJobId,assetId:data.assetId,importTaskId:data.importTaskId,
  fileName:data.uploadFileName,kind:data.kind,sourceSha256:data.sourceSha256,sourceFileBytes:data.sourceFileBytes,
  uploadStatusCode:response.statusCode},pairedItem:{item:0}}];

const crypto=require('crypto');
const item=$input.first(),data=item.json;
if(data.uploadRequired!==false) throw new Error('Only accepted imports may be reused.');
const source=await this.helpers.getBinaryDataBuffer(0,'file');
return [{json:{cloudConvertJobId:data.cloudConvertJobId,assetId:data.assetId,importTaskId:data.importTaskId,
  fileName:data.uploadFileName,kind:data.kind,sourceSha256:crypto.createHash('sha256').update(source).digest('hex'),
  sourceFileBytes:source.length,reusedImport:true},pairedItem:{item:0}}];

const inputs=$input.all();
const attached=$('Attach CloudConvert Job').first().json;
const previous=inputs[0]?.json;
const receipts=Array.isArray(previous?.uploadReceipts)?previous.uploadReceipts:inputs.map(i=>i.json);
if(receipts.length!==attached.uploadPlan.length || new Set(receipts.map(r=>r.assetId)).size!==receipts.length ||
   receipts.some(r=>r.cloudConvertJobId!==attached.cloudConvertJobId || !/^[0-9a-f]{64}$/.test(r.sourceSha256)))
  throw new Error('Upload receipt set is incomplete or mismatched.');
const pollAttempt=(previous?.pollAttempt||0)+1;
if(pollAttempt>120) throw new Error('Timed out waiting for the existing job. Resume it; do not create another.');
return [{json:{pieceFolderId:attached.pieceFolderId,cloudConvertJobId:attached.cloudConvertJobId,
  jobTag:attached.jobPayload.tag,jobFingerprint:attached.jobFingerprint,
  outputZipFilename:attached.jobSummary.outputZipFilename,uploadReceipts:receipts,pollAttempt},pairedItem:{item:0}}];

const context=$('Prepare Job Poll').itemMatching(0).json;
const job=$input.first().json.data;
const planned=$('Build CloudConvert Job').first().json.jobPayload.tasks;
if(!job || job.id!==context.cloudConvertJobId || job.tag!==context.jobTag || !Array.isArray(job.tasks) ||
   job.tasks.length!==Object.keys(planned).length || new Set(job.tasks.map(t=>t.name)).size!==job.tasks.length)
  throw new Error('Unexpected job status response.');
for(const task of job.tasks){
  if(task.job_id!==job.id || task.operation!==planned[task.name]?.operation) throw new Error('Mismatched job task.');
  if(task.status==='error') throw new Error('CloudConvert '+task.name+': '+task.code+' '+task.message);
}
if(job.status==='error') throw new Error('CloudConvert job failed.');
if(!['waiting','processing','finished'].includes(job.status)) throw new Error('Unknown job status.');
if(job.status!=='finished') return [{json:{...context,jobFinished:false,jobStatus:job.status},pairedItem:{item:0}}];
if(job.tasks.some(t=>t.status!=='finished')) throw new Error('Job task set has not finished.');
const expectedFiles=[];
