  if(receipt.kind==='image') expectedFiles.push({fileName:receipt.fileName,sha256:receipt.sourceSha256,bytes:receipt.sourceFileBytes,kind:'image'});
  else{
    const task=job.tasks.find(t=>t.name==='extract-'+receipt.assetId);
    const files=task?.result?.files;
    if(!Array.isArray(files)||!files.length) throw new Error('No frames returned for '+receipt.assetId);
    const pattern=new RegExp('^'+receipt.assetId+'_frame_[0-9]{6,}\\.jpg$');
    for(const f of files){
      if(!pattern.test(f.filename)) throw new Error('Unexpected extracted frame name.');
      expectedFiles.push({fileName:f.filename,kind:'frame'});
    }
  }
}
if(new Set(expectedFiles.map(f=>f.fileName)).size!==expectedFiles.length) throw new Error('Duplicate output file names.');
