const crypto=require('crypto');
const context=$('Prepare ZIP Validation').itemMatching(0).json;
const item=$input.first();
const expected=new Map(context.expectedFiles.map(f=>[f.fileName,f]));
const seen=new Set();
for(const [field,file] of Object.entries(item.binary||{})){
  if(field==='outputZip') continue;
  const full=file.fileName;
  if(typeof full!=='string' || /(^\/|(^|\/)\.\.(\/|$)|\\|\0)/.test(full)) throw new Error('Unsafe ZIP entry.');
  const name=full.split('/').pop();
  const spec=expected.get(name);
  if(!spec||seen.has(name)) throw new Error('Unexpected or duplicate ZIP entry: '+name);
  const bytes=await this.helpers.getBinaryDataBuffer(0,field);
  if(spec.kind==='image'){
    if(bytes.length!==spec.bytes || crypto.createHash('sha256').update(bytes).digest('hex')!==spec.sha256)
      throw new Error('Original image bytes changed: '+name);
  }else if(bytes.length<4 || bytes[0]!==255 || bytes[1]!==216 || bytes[bytes.length-2]!==255 || bytes[bytes.length-1]!==217)
    throw new Error('Invalid JPEG frame: '+name);
  seen.add(name);
}
if(seen.size!==expected.size) throw new Error('ZIP is missing expected files.');
const zip=$('Prepare ZIP Validation').itemMatching(0).binary.outputZip;
const {expectedFiles,metadataTasks,...safe}=context;
return [{json:{...safe,zipVerified:true,verifiedFileCount:seen.size,originalImagesByteIdentical:true},binary:{outputZip:zip},pairedItem:{item:0}}];

const response=$input.first().json;
