if(!Array.isArray(response.files)||response.nextPageToken||response.files.length>1) throw new Error('Output lookup is ambiguous.');
const existing=response.files[0];
if(existing && (existing.name!==context.outputZipFilename||!existing.parents?.includes(context.pieceFolderId)||
  Number(existing.size)!==context.outputZipBytes||existing.md5Checksum!==context.outputZipMd5))
  throw new Error('An output with this name already exists but does not match. Nothing overwritten.');
return [{json:{...context,outputExists:!!existing,existingOutputFile:existing||null},binary:item.binary,pairedItem:{item:0}}];

